import time
import aiosqlite
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel, field_validator

from .config import SearchRecConfig


class ClickEvent(BaseModel):
    session_id: str
    item_id:    str
    query:      str = ""
    position:   int = 0

    @field_validator("session_id", "item_id")
    @classmethod
    def must_be_non_empty(cls, v: str) -> str:
        if not v.strip():
            raise ValueError("must not be empty")
        return v.strip()

    @field_validator("position")
    @classmethod
    def position_non_negative(cls, v: int) -> int:
        if v < 0:
            raise ValueError("position must be >= 0")
        return v


class ClickBatch(BaseModel):
    events: list[ClickEvent]

    @field_validator("events")
    @classmethod
    def batch_size_limit(cls, v: list[ClickEvent]) -> list[ClickEvent]:
        if len(v) == 0:
            raise ValueError("batch must contain at least one event")
        if len(v) > 100:
            raise ValueError("batch size limit is 100 events")
        return v


def tracker_router(config: SearchRecConfig) -> APIRouter:
    router = APIRouter()

    @router.post("/api/track", status_code=204, tags=["tracking"])
    async def track_clicks(batch: ClickBatch):
        now_ms = int(time.time() * 1000)
        # Offset each event by 1ms so within-batch click order is recoverable via ts
        rows = [
            (e.session_id, e.item_id, e.query, e.position, now_ms + i)
            for i, e in enumerate(batch.events)
        ]
        try:
            async with aiosqlite.connect(config.db_path) as db:
                await db.executemany(
                    "INSERT INTO click_events (session_id, item_id, query, position, ts) VALUES (?, ?, ?, ?, ?)",
                    rows,
                )
                await db.commit()
        except Exception as e:
            raise HTTPException(status_code=500, detail=f"DB write failed: {e}")

    return router


async def get_recent_session_items(db_path: str, session_id: str, limit: int = 5) -> list[str]:
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute(
            "SELECT item_id FROM click_events WHERE session_id = ? ORDER BY ts DESC LIMIT ?",
            (session_id, limit),
        )
        rows = await cursor.fetchall()
    return [r["item_id"] for r in rows]


async def get_click_counts(db_path: str) -> dict:
    async with aiosqlite.connect(db_path) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute(
            "SELECT item_id, COUNT(*) as cnt FROM click_events GROUP BY item_id ORDER BY cnt DESC"
        )
        rows = await cursor.fetchall()
    return {r["item_id"]: r["cnt"] for r in rows}
